fun main() {
    println("hello world foo".split(" ").map { it.replaceFirstChar(Char::uppercaseChar) }.joinToString(" "))
    println("a1b2".filter(Char::isDigit))
    println("Hello".startsWith("He") to "Hello".endsWith("lo") to "Hello".contains("ell"))
    println("hello".removePrefix("he") + "hello".removeSuffix("lo"))
    println("a b  c".split(" "))
    println("a b  c".split(Regex("\\s+")))
    println("abc".padStart(2) + "|" + "abc".padEnd(6, '-'))
    println("ab".compareTo("ac") to "b".compareTo("a"))
    println("kotlin".take(3) + "kotlin".takeLast(2) + "kotlin".takeWhile { it != 't' })
    println("x,y;z".split(',', ';'))
    println("trim\n".trimEnd() + "|" + "  s".trimStart())
    println("a-b".replace('-', '+') + "aaa".replace("aa", "b"))
    println("Mississippi".groupBy { it }.mapValues { it.value.size })
    println("abc".zip("xyz"))
    println("hello".chunked(2))
    println("hello".windowed(3))
    println("one two".split(" ").reversed().joinToString(" "))
    println("racecar" == "racecar".reversed())
    println("a".isBlank() to "  ".isBlank() to "".isEmpty() to " ".isNotEmpty())
    println("text".firstOrNull() to "".firstOrNull())
    println("abc".last() + "abc".first().toString())
    println("AbC".map { if (it.isUpperCase()) it.lowercaseChar() else it.uppercaseChar() }.joinToString(""))
    println("a=1;b=2".split(';').associate { it.substringBefore('=') to it.substringAfter('=').toInt() })
    println("%s".format("x"))
    println("abc".indices)
    println("abc".lastIndex)
    println("hello"[1])
    println("hello".getOrNull(10))
    println("hello".substring(2))
    println("TitleCase".decapitalize2())
    println("a\u0000b".length)
    println("ß".uppercase())
    println("İ".lowercase().length)
    println("ǆ".uppercase())
    println("abc".hashCode())
    println("".hashCode())
    println("hello world".hashCode())
    println("é".toByteArray().size)
    println("日本".toByteArray().toList().size)
    println(String("hi".toByteArray()))
    println("abc".encodeToByteArray().decodeToString())
    println("a".codePointAt(0))
    println("Zebra".equals("zebra", true))
    println("hello".commonPrefixWith("help"))
    println("2" + 2 * 2)
    println("a".repeat(0).isEmpty())
}

fun String.decapitalize2() = replaceFirstChar { it.lowercase() }
